public data class BotTaskDefinition(
    val id: String,
    val kind: BotTaskKind,
    val weight: Int,
    val start: CoordGrid,
    val route: List<CoordGrid>,
    val targets: Set<String>,
    val option: String,
    val skill: String?,
    val minimumLevel: Int = 1,
    val maximumLevel: Int = 99,
    val members: Boolean = false,
    val requiredItems: Map<String, Int> = emptyMap(),
    val ignoredLoot: Set<String> = emptySet(),
    val requiredLevels: Map<String, Int> = emptyMap(),
    val minimumCombatLevel: Int = 3,
    val maximumCombatLevel: Int = 126,
    val progressionBelow: Map<String, Int> = emptyMap(),
    val progressionAnyBelow: Boolean = false,
)

